// Small rule drawing (generated by tools/gen_swatches.py into static/img/swatches). Click to show the rule's JSON.
// Carries .pm-graphic so the navbar graphics switch hides it.
import React, {useState} from 'react';
import ThemedImage from '@theme/ThemedImage';
import useBaseUrl from '@docusaurus/useBaseUrl';

export default function Swatch({name, json}) {
  const [open, setOpen] = useState(false);
  const light = useBaseUrl(`/img/swatches/${name}.svg`);
  const dark = useBaseUrl(`/img/swatches/${name}-dark.svg`);
  const alt = name.replace(/[-_]/g, ' ');
  const img = <ThemedImage alt={alt} width={72} sources={{light, dark}} style={{display: 'block'}}/>;
  return (
    <span className="pm-graphic pm-swatch" style={{display: 'inline-block', margin: '2px 4px 2px 0', verticalAlign: 'top'}}>
      {json ? (
        <button type="button" className="clean-btn" style={{padding: 0, cursor: 'pointer'}} title="Show the rule's JSON"
                onClick={() => setOpen(!open)}>{img}</button>
      ) : img}
      {open && json && <pre style={{fontSize: '0.7rem', margin: '4px 0 0', maxWidth: '16rem', whiteSpace: 'pre-wrap'}}>{json}</pre>}
    </span>
  );
}
